ions": "Kortin loppuvuosi 1945 on keruurajaus, ei lakkautusvuosi. Ministeriön nimi tai olemassaolo ei osoita tiettyä säännöstelyvaltuutta: lainkohdat ja käyttöpäätökset tarkistettava.", "formal_authority_status": "institution_in_operation_scope_clipped", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1918_1945_20261026:engagement1940", "primary_item_id": "civil_society_1939_1951_20261022:engagement1940", "reuse_existing_item": true, "title": "Neuvottelutunnustus ilman välitöntä kattavaa sopimusjärjestelmää", "year_start": 1940, "year_end": 1940, "theme_ids": [15, 21, 22, 25], "dimension_codes": ["access_representation", "resource_control"], "source_ids": ["engagement"], "observations": [{"observation_id": "institutional_power_1918_1945_20261026:engagement1940:1", "statement": "SAK ja STK antoivat tammikuussa 1940 yhteisen julkilausuman. SAK:n tutkijan mukaan sen välitön sopimusoikeudellinen merkitys jäi rajalliseksi.", "source_ids": ["engagement"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["SAK", "STK"], "affected_groups": ["palkansaajat", "työnantajat"], "mechanism_hypothesis": "Tunnustaminen saattoi avata neuvottelukanavia, vaikka sopimuskattavuus ei syntynyt yhdellä päätöksellä.", "case_limitations": "Osapuolen julkaisema historiatulkinta; ei riippumaton kattavuus- tai palkkavaikutusarvio.", "formal_authority_status": "documented_arrangement", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1918_1945_20261026:information1941", "primary_item_id": "knowledge_power_1918_1945_20261024:information1941", "reuse_existing_item": true, "title": "Tiedotus- ja sensuuritoiminnan keskittäminen", "year_start": 1941, "year_end": 1941, "theme_ids": [8, 12, 19, 29]